72: /**
73:  * Standard HTTP/HTTPS request helper returning Promise
74:  */
75: function request(options, requestBody) {
76:   return new Promise(function (resolve, reject) {
77:     const isHttps = options.protocol === 'https:';
78:     const client = isHttps ? https : http;
79: 
80:     const reqOpts = Object.assign({}, options);
81:     reqOpts.headers = Object.assign({}, options.headers || {});
82: 
83:     if (requestBody && !reqOpts.headers['Content-Length'] && !reqOpts.headers['content-length']) {
84:       reqOpts.headers['Content-Length'] = Buffer.isBuffer(requestBody)
85:         ? requestBody.length
86:         : Buffer.byteLength(requestBody);
87:     }
88: 
89:     const req = client.request(reqOpts, function (res) {
90:       const chunks = [];
91:       res.on('data', function (chunk) {
92:         chunks.push(chunk);
93:       });
94:       res.on('end', function () {
95:         const rawBuffer = Buffer.concat(chunks);
96:         let text = null;
97:         let json = null;
98:         try {
99:           text = rawBuffer.toString('utf8');
100:           json = JSON.parse(text);
101:         } catch (_) {}
102:         resolve({
103:           statusCode: res.statusCode,
104:           headers: res.headers,
105:           buffer: rawBuffer,
106:           text: text,
107:           json: json
108:         });
109:       });
110:     });
111: 
112:     req.on('error', reject);
113: 
114:     const timeoutMs = options.timeout || 25000;
115:     req.setTimeout(timeoutMs, function () {
116:       req.abort();
117:       reject(new Error('Request timed out after ' + timeoutMs + 'ms'));
118:     });
119: 
120:     if (requestBody) {
121:       req.write(requestBody);
122:     }
123:     req.end();
124:   });
125: }
